package com.aistock.market.marketlifecycle;
import com.aistock.common.*;import com.aistock.common.marketlifecycle.*;import com.aistock.common.marketlifecycle.MarketUseRecords.*;import com.aistock.market.comparison.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import static com.aistock.market.marketlifecycle.MarketLifecycleRecords.*;
/** Original market comparison operation owns its full read/collect/publish lifetime. */
public final class MarketComparisonUseOwner {
 private record Binding(String request,String raw,Bundle receipt,boolean started,boolean acked){}
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final ComparisonRefreshRepository records;private final MarketLifecycleService lifecycle;private final MarketEvidenceGate gate;private final Clock clock;private final boolean enabled;private final TransactionTemplate tx;
 public MarketComparisonUseOwner(JdbcTemplate jdbc,ObjectMapper json,ComparisonRefreshRepository records,MarketLifecycleService lifecycle,MarketEvidenceGate gate,Clock clock,boolean enabled){this.jdbc=jdbc;this.json=json;this.records=records;this.lifecycle=lifecycle;this.gate=gate;this.clock=clock;this.enabled=enabled;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);}
 public boolean enabled(){return enabled;}
 private UseIdentity identity(UUID operation){return new UseIdentity("market","COMPARISON_EVIDENCE_PUBLISH",operation.toString(),"1");}
 public MarketEvidenceGate.Scope acquire(ComparisonUpdateRecords.Request request){if(!enabled)return MarketEvidenceGate.passthrough();if(!gate.enabled())throw unavailable();var b=prepare(request);if(b.receipt()==null){Bundle bundle;if(b.started())bundle=lifecycle.registration(b.request(),identity(request.operationId()));else if(start(request))bundle=lifecycle.register(b.request(),identity(request.operationId()),new Selector("RAW_VERSIONS",List.of(b.raw()),null,null),true);else bundle=lifecycle.registration(b.request(),identity(request.operationId()));attach(request.operationId(),bundle);b=read(request.operationId());}records.marketUseInput(request);if(!"ACTIVE".equals(b.receipt().state()))throw unavailable();return gate.open(b.receipt().bundleId(),identity(request.operationId()),Set.of("COMPARISON_EVIDENCE_PUBLISH"));}
 private Binding prepare(ComparisonUpdateRecords.Request request){return tx.execute(s->{var raw=records.marketUseInput(request);var old=read(request.operationId());if(old!=null){if(!raw.equals(old.raw()))throw unavailable();return old;}jdbc.update("insert into market_local_comparison_use(operation_id,request_id,raw_version_id,created_at,last_checked_at) values(?,?,?,?,?)",request.operationId().toString(),UUID.randomUUID().toString(),raw,ts(),ts());return read(request.operationId());});}
 private boolean start(ComparisonUpdateRecords.Request request){return Boolean.TRUE.equals(tx.execute(s->{records.marketUseInput(request);return jdbc.update("update market_local_comparison_use set registration_started=true where operation_id=? and registration_started=false",request.operationId().toString())==1;}));}
 private Binding read(UUID operation){var rows=jdbc.queryForList("select * from market_local_comparison_use where operation_id=?",operation.toString());if(rows.isEmpty())return null;var r=rows.get(0);try{return new Binding(r.get("request_id").toString(),r.get("raw_version_id").toString(),r.get("receipt_json")==null?null:json.readValue(r.get("receipt_json").toString(),Bundle.class),Boolean.TRUE.equals(r.get("registration_started")),Boolean.TRUE.equals(r.get("completion_acked")));}catch(java.io.IOException e){throw unavailable();}}
 private void attach(UUID operation,Bundle receipt){tx.executeWithoutResult(s->{jdbc.queryForMap("select * from market_local_comparison_use where operation_id=? for update",operation.toString());var b=read(operation);if(b==null||!b.started()||!identity(operation).equals(receipt.identity())||!List.of(b.raw()).equals(receipt.versionIds()))throw unavailable();if(b.receipt()!=null){if(!b.receipt().bundleId().equals(receipt.bundleId())||!b.receipt().versionIds().equals(receipt.versionIds()))throw unavailable();return;}jdbc.update("update market_local_comparison_use set bundle_id=?,receipt_json=? where operation_id=? and bundle_id is null",receipt.bundleId(),encode(receipt),operation.toString());});}
 private TerminalProof terminal(UUID operation,String generation){if(!"1".equals(generation))throw unavailable();var b=read(operation);if(b==null||b.receipt()==null)throw unavailable();return records.executionTerminal(operation,b.receipt().versionIds());}
 public JsonNode proof(UUID operation,String generation){var p=terminal(operation,generation);var n=json.createObjectNode();n.put("owner",p.identity().owner()).put("purpose",p.identity().purpose()).put("ownerOperationId",p.identity().ownerOperationId()).put("generation",p.identity().generation()).put("state",p.state()).put("terminalAt",p.terminalAt().toString()).put("fencingRevision",p.fencingRevision()).put("resultIdentity",p.resultIdentity());n.set("versionIds",json.valueToTree(p.versionIds()));return n;}
 public void notifyCompleted(UUID operation){if(!enabled)return;try{var b=read(operation);if(b==null||b.receipt()==null||b.acked())return;var p=terminal(operation,"1");mark(operation.toString());lifecycle.releaseVerified(b.receipt().bundleId(),p);jdbc.update("update market_local_comparison_use set completion_acked=true where operation_id=? and bundle_id=?",operation.toString(),b.receipt().bundleId());}catch(RuntimeException ignored){/* Preserve durable result/use; never infer terminal from TTL. */}}
 public void recoverOne(UUID operation){if(!enabled)return;try{mark(operation.toString());var b=read(operation);if(b==null||b.acked()||!b.started())return;if(b.receipt()==null)attach(operation,lifecycle.registration(b.request(),identity(operation)));notifyCompleted(operation);}catch(RuntimeException ignored){/* Only original registration lookup, no new register or calculation. */}}
 public void recoverBatch(){if(!enabled)return;for(var id:jdbc.queryForList("select operation_id from market_local_comparison_use where registration_started=true and completion_acked=false order by last_checked_at,operation_id limit 25",String.class)){mark(id);try{recoverOne(UUID.fromString(id));}catch(RuntimeException ignored){/* Malformed records rotate conservatively. */}}}
 private void mark(String operation){jdbc.update("update market_local_comparison_use set last_checked_at=greatest(?,timestampadd(microsecond,1000,last_checked_at)) where operation_id=?",ts(),operation);}private Timestamp ts(){return Timestamp.from(clock.instant());}private String encode(Object value){try{return json.writeValueAsString(value);}catch(java.io.IOException e){throw unavailable();}}
 public static BusinessException unavailable(){return new BusinessException("MARKET_USE_UNAVAILABLE","比较行情使用状态暂不能核对，原请求保留",HttpStatus.SERVICE_UNAVAILABLE);}
}
